@RestController
@RequestMapping("/api/orders")
public class OrderController {
    private final OrderService orderService;

    @GetMapping("/{orderId}")
    @PreAuthorize("isAuthenticated()") // A01: Access control at method level
    public ResponseEntity<OrderDTO> getOrder(
            @PathVariable Long orderId,
            @AuthenticationPrincipal User user) {

        // A01: Verify resource ownership - critical step
        var order = orderService.findById(orderId)
            .orElseThrow(() -> new ResourceNotFoundException("Order not found"));

        if (!order.getUserId().equals(user.getId())) {
            throw new AccessDeniedException("Not authorized to view this order");
        }

        return ResponseEntity.ok(mapToDTO(order));
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<ErrorResponse> handleError(Exception ex) {
        // A05: Don't leak stack traces in production
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
            .body(new ErrorResponse("An error occurred"));
    }
}

@RestController
@RequestMapping("/api/orders")
public class OrderController {
    private final OrderRepository orderRepository;

    @GetMapping("/{orderId}")
    @PreAuthorize("isAuthenticated()") // Method-level security
    public ResponseEntity<Order> getOrder(
            @PathVariable Long orderId,
            @AuthenticationPrincipal UserDetails currentUser) {

        var order = orderRepository.findById(orderId)
            .orElseThrow(() -> new ResourceNotFoundException("Order not found"));

        // Critical: verify resource ownership
        if (!order.getUsername().equals(currentUser.getUsername())) {
            throw new AccessDeniedException("You can only view your own orders");
        }

        return ResponseEntity.ok(order);
    }

    @DeleteMapping("/{orderId}")
    @PreAuthorize("hasRole('ADMIN')")
    public ResponseEntity<Void> deleteOrder(@PathVariable Long orderId) {
        // Admin-only endpoint with role-based access control
        orderRepository.deleteById(orderId);
        return ResponseEntity.noContent().build();
    }
}

